# Generates lean/Coercions/Selective/FsubCompare/Family.lean; run from the repository root
# (per-n instances with numeral n, so that the
# Nat arithmetic in the indices of Cert.narrow / Cert.inst reduces by evaluation).
N = 9
out = []
w = out.append
w('''import Coercions.Selective.FsubCompare.Measure
/-!
# The chain family `X₀ <: Top → Top, Xᵢ₊₁ <: Xᵢ`  (GENERATED by gen/family.py)

`chainCtx n` has the variables `X₀ … Xₙ` (`Xₙ = var 0`, `X₀ = var n`). The chain
`Xₙ ⇒ … ⇒ X₀ ⇒ Top → Top` has `n+1` bound steps. The universal chain `U₀ ⇒ … ⇒ Uₙ`
with `Uᵢ = ∀(Z <: Xᵢ). Z → Top` has `n` bound changes.
-/
namespace Compare.Fam
open Compare
open SelFsub (Ty Ctx Cert Sub synthC)

abbrev tt : Ty n := .arr .top .top

def chainCtx : (n : Nat) → Ctx (n+1)
  | 0 => .snoc .nil tt
  | n+1 => .snoc (chainCtx n) (.var 0)

/-- Hand-minimal: one `step` per bound, right-nested `;`. -/
def chainCert : (n : Nat) → Cert (n+1)
  | 0 => .step (.var 0) tt
  | n+1 => .seq (.step (.var 0) (.var (Fin.succ 0))) (chainCert n).weaken

/-- `Uᵢ = ∀(Z <: Xᵢ). Z → Top`. -/
def uTy (n i : Nat) : Ty (n+1) := .all (.var (Fin.ofNat (n+1) (n - i))) (.arr (.var 0) .top)

/-- Hand-minimal universal chain: links `i+1 … i+m`, one step each. -/
def uFrom (n i : Nat) : (m : Nat) → Cert (n+1)
  | 0 => .step (uTy n i) (uTy n i)
  | 1 => .step (uTy n i) (uTy n (i+1))
  | m+2 => .seq (.step (uTy n i) (uTy n (i+1))) (uFrom n (i+1) (m+1))
def uCert (n : Nat) : Cert (n+1) := uFrom n 0 n

/-- `d : (Top → Top) → Top → Top ⇒ Top → Top`-style narrowing witness: `U' = Top → (Top → Top)`. -/
def dNarrow : Cert 0 := .step (.arr .top tt) tt
def Ubig : Ty 0 := .arr .top tt

/-- A composite `d : V ⇒ V' ⇒ Top → Top` with `V = Top → Top → Top → Top`. -/
def dInst : Cert 0 :=
  .seq (.step (.arr .top (.arr .top tt)) (.arr .top tt)) (.step (.arr .top tt) tt)
def Vinst : Ty 0 := .arr .top (.arr .top tt)

/-- `X₀ <: U'` for the narrowed family. -/
def chainCtxU : (n : Nat) → Ctx (n+1)
  | 0 => .snoc .nil Ubig
  | n+1 => .snoc (chainCtxU n) (.var 0)

def narrowedCtx : (n : Nat) → Ctx (n+1) := chainCtxU

''')
for n in range(N):
    # Sub derivation for the bound chain
    def chain(i):
        if i == n: return f"(.bound {i})"
        return f"(.trans (.bound {i}) {chain(i+1)})"
    w(f"def chainSub{n} : Sub (chainCtx {n}) (.var 0) tt := {chain(0)}")
    # universal chain derivation: link i (1..n): Sub.all (bound (n-i)) refl
    def link(i): return f"(.all (.bound {n-i}) .refl)"
    def uch(i):
        if n == 0: return ".refl"
        if i == n: return link(i)
        return f"(.trans {link(i)} {uch(i+1)})"
    w(f"def uSub{n} : Sub (chainCtx {n}) (uTy {n} 0) (uTy {n} {n}) := {uch(1)}")
w("")
w("def selRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row (chainCert {n}))" + ("," if n < N-1 else ""))
w("]")
w("def mechRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row chainSub{n}.toCert)" + ("," if n < N-1 else ""))
w("]")
w("def narrowRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row (Cert.narrow {n} (chainCert {n}) dNarrow))" + ("," if n < N-1 else ""))
w("]")
w("def instOuterRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row (Cert.inst (n := 0) {n} (chainCert {n}) Vinst dInst))" + ("," if n < N-1 else ""))
w("]")
# inner inst: at X_n (k=0); V = X_{n-1} = var 0 : Ty n (n>=1); n=0: V = tt, d = step tt tt
w("def instInnerRows : List (Nat × List Nat) := [")
for n in range(N):
    if n == 0:
        w(f"  (0, Sel.row (Cert.inst (n := 0) 0 (chainCert 0) (tt : Ty 0) (.step tt tt)))" + ",")
    else:
        w(f"  ({n}, Sel.row (Cert.inst (n := {n}) 0 (chainCert {n}) (.var 0) (.step (.var 0) (.var 0))))" + ("," if n < N-1 else ""))
w("]")
w("def uRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row (uCert {n}))" + ("," if n < N-1 else ""))
w("]")
w("def uMechRows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row uSub{n}.toCert)" + ("," if n < N-1 else ""))
w("]")
# allInv: component 1 (bound, Cert (n+1)) and 2 (body, Cert (n+2)) of hand and mechanical
w("def allInvHandRows : List (Nat × List Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row (uCert {n}).allInv.1, Sel.row (uCert {n}).allInv.2)" + ("," if n < N-1 else ""))
w("]")
w("def allInvMechRows : List (Nat × List Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Sel.row uSub{n}.toCert.allInv.1, Sel.row uSub{n}.toCert.allInv.2)" + ("," if n < N-1 else ""))
w("]")
# checker acceptance
w("")
for n in range(N):
    w(f"theorem chainOk{n} : synthC (chainCtx {n}) (chainCert {n}) = some (.var 0, tt) := by decide")
    w(f"theorem chainMech{n} : chainSub{n}.toCert = chainCert {n} := by decide")
    w(f"theorem narrowOk{n} : synthC (chainCtxU {n}) (Cert.narrow {n} (chainCert {n}) dNarrow) = some (.var 0, tt) := by decide")
    w(f"theorem uOk{n} : synthC (chainCtx {n}) (uCert {n}) = some (uTy {n} 0, uTy {n} {n}) := by decide")
    w(f"theorem uMechOk{n} : synthC (chainCtx {n}) uSub{n}.toCert = some (uTy {n} 0, uTy {n} {n}) := by decide")
w("")
w("#eval selRows\n#eval mechRows\n#eval narrowRows\n#eval instOuterRows\n#eval instInnerRows\n#eval uRows\n#eval uMechRows\n#eval allInvHandRows\n#eval allInvMechRows")

w("def fcChainRows : List (Nat × List Nat × Nat) := [")
for n in range(N):
    w(f"  ({n}, Fc.row (Fc.cnt (leOf chainSub{n})), Fc.dag (leOf chainSub{n}))" + ("," if n < N-1 else ""))
w("]")
w("def fcURows : List (Nat × List Nat) := [")
for n in range(N):
    w(f"  ({n}, Fc.row (Fc.cnt (leOf uSub{n})))" + ("," if n < N-1 else ""))
w("]")
for n in range(N):
    w(f"theorem fcChainOk{n} : FCsub.synthLe (ctxOf (chainCtx {n})) (leOf chainSub{n}) = some (tyOf (.var 0), tyOf tt) := by decide +kernel")
    w(f"theorem fcUOk{n} : FCsub.synthLe (ctxOf (chainCtx {n})) (leOf uSub{n}) = some (tyOf (uTy {n} 0), tyOf (uTy {n} {n})) := by decide +kernel")
w("#eval fcChainRows\n#eval fcURows")
w("\nend Compare.Fam")
open("lean/Coercions/Selective/FsubCompare/Family.lean","w").write("\n".join(out)+"\n")
